// ═══════════════════════════════════════════════
// AUDIO
// ═══════════════════════════════════════════════
const AC = new (window.AudioContext||window.webkitAudioContext)();
function snd(type, x=0) {
    try {
        if(AC.state==='suspended') AC.resume();
        const g=AC.createGain(), p=AC.createStereoPanner(), o=AC.createOscillator();
        p.pan.value=Math.max(-1,Math.min(1,(x-canvas.width/2)/(canvas.width/2)||0));
        o.connect(p); p.connect(g); g.connect(AC.destination);
        const t=AC.currentTime;
        const cfg={
            shoot:  [o=>'sawtooth',800,200,0.09,0.06,0.09],
            hit:    [o=>'square', 300,80, 0.07,0.08,0.08],
            death:  [o=>'square', 200,40, 0.15,0.08,0.16],
            dash:   [o=>'sine',   200,1200,0.12,0.15,0.15],
            nova:   [o=>'sawtooth',100,50,0.25,0.4,0.4],
            hurt:   [o=>'sawtooth',120,60,0.18,0.22,0.22],
            shield: [o=>'sine',   400,800,0.1,0.22,0.22],
            chest:  [o=>'triangle',660,0, 0.1,0.25,0.3],
            levelup:[o=>'sine',   440,880,0.12,0.2,0.25],
        };
        const c=cfg[type]; if(!c)return;
        o.type=c[0]();
        o.frequency.setValueAtTime(c[1],t);
        if(c[2]) o.frequency.exponentialRampToValueAtTime(c[2],t+c[4]);
        g.gain.setValueAtTime(c[3],t);
        g.gain.exponentialRampToValueAtTime(0.001,t+c[5]);
        o.start(t); o.stop(t+c[5]+0.01);
    } catch(e){}
}

