// World size
const WORLD_W = 3200, WORLD_H = 3200;

// Camera: world position of screen center
const cam = { x: WORLD_W/2, y: WORLD_H/2 };
const zoom = 0.6; // ← dézoom (1 = normal, <1 = plus éloigné)

// Resize
function resize() {
    canvas.width  = window.innerWidth;
    canvas.height = window.innerHeight;
}
resize();
window.addEventListener('resize', () => { resize(); });
window.addEventListener('orientationchange', () => setTimeout(resize, 300));

// World → Screen conversion (avec zoom)
function w2s(wx, wy) {
    return {
        x: (wx - cam.x) * zoom + canvas.width / 2,
        y: (wy - cam.y) * zoom + canvas.height / 2
    };
}

// ═══════════════════════════════════════════════
// ASSETS (mob spritesheet + lava bg)
// ═══════════════════════════════════════════════
const IMG_MOBS_B64 = '';
const IMG_BG_B64   = '';
const IMG_DECOR_B64 = '';;

let mobSheet=null, bgImg=null, decorImg=null, ssLoaded=false, bgLoaded=false, decorLoaded=false;
// Mob spritesheet: 6 cols × 4 rows, ~194×196px per frame
const SS_COLS=6, SS_ROWS=4;
let ssW=0, ssH=0;
const MOB_COL={rat:0,skeleton:1,slime:2,goblin:3,bat:4,zombie:5};
const MOB_FPS={normal:9,fast:13,tank:6,specter:11,sniper:12,splitter:10,blue:10,miniboss:7,boss:8};

// Per-frame cached canvases (chromakeyed)
const frameCache = {};

function chromakey(img, tol) {
    const oc=document.createElement('canvas');
    oc.width=img.width; oc.height=img.height;
    const c=oc.getContext('2d');
    c.drawImage(img,0,0);
    const id=c.getImageData(0,0,oc.width,oc.height), d=id.data;
    const W=oc.width, H=oc.height;
    let rS=0,gS=0,bS=0,n=0;
    for(let s=0;s<20;s++){
        const t=Math.floor(s/20*Math.min(W,H));
        [[t,0],[t,H-1],[0,t],[W-1,t]].forEach(([x,y])=>{
            const i=(y*W+x)*4; rS+=d[i]; gS+=d[i+1]; bS+=d[i+2]; n++;
        });
    }
    const bgR=rS/n|0, bgG=gS/n|0, bgB=bS/n|0;
    const soft=tol+22;
    for(let i=0;i<d.length;i+=4){
        const dist=Math.max(Math.abs(d[i]-bgR),Math.abs(d[i+1]-bgG),Math.abs(d[i+2]-bgB));
        if(dist<tol) d[i+3]=0;
        else if(dist<soft) d[i+3]=Math.round((dist-tol)/(soft-tol)*255);
    }
    c.putImageData(id,0,0); return oc;
}

function loadAssets(cb) {
    let done = 0;
    const total = 3 + 9;
    const check = () => { if (++done >= total) cb(); };

    const m = new Image();
    m.onload = () => {
        ssW = Math.round(m.width/SS_COLS); ssH = Math.round(m.height/SS_ROWS);
        mobSheet = chromakey(m, 42); ssLoaded = true;
        for(let c=0;c<SS_COLS;c++) for(let r=0;r<SS_ROWS;r++){
            const fc = document.createElement('canvas');
            fc.width = ssW; fc.height = ssH;
            fc.getContext('2d').drawImage(mobSheet,c*ssW,r*ssH,ssW,ssH,0,0,ssW,ssH);
            frameCache[c+'_'+r] = fc;
        }
        check();
    };
    m.onerror = () => check();
    m.src = 'data:image/jpeg;base64,' + IMG_MOBS_B64;

    const b = new Image();
    b.onload = () => { bgImg = b; bgLoaded = true; check(); };
    b.onerror = () => check();
    b.src = 'data:image/jpeg;base64,' + IMG_BG_B64;

    const d = new Image();
    d.onload = () => { decorImg = d; decorLoaded = true; check(); };
    d.onerror = () => check();
    d.src = 'data:image/jpeg;base64,' + IMG_DECOR_B64;

    // 9 tuiles
    const tileDefs = [
        ['centre', IMG_TILE_CENTRE_B64],
        ['hg',     IMG_TILE_HG_B64],
        ['hd',     IMG_TILE_HD_B64],
        ['bg',     IMG_TILE_BG_B64],
        ['bd',     IMG_TILE_BD_B64],
        ['mh',     IMG_TILE_MH_B64],
        ['mb',     IMG_TILE_MB_B64],
        ['mg',     IMG_TILE_MG_B64],
        ['md',     IMG_TILE_MD_B64],
    ];
    tileDefs.forEach(([key, b64]) => {
        const img = new Image();
        img.onload = () => { tileImgs[key] = img; check(); };
        img.onerror = () => check();
        img.src = 'data:image/jpeg;base64,' + b64;
    });
}

