// ═══════════════════════════════════════════════
// INPUT — keyboard
// ═══════════════════════════════════════════════
addEventListener('keydown', e=>{
    keys[e.key.toLowerCase()]=true;
    if(e.code==='KeyP') togglePause();
    if(e.key.toLowerCase()==='u'){
        const ov=document.getElementById('upgradeOverlay');
        if(ov && ov.style.display==='block') closeUpgradeTree(); else openUpgradeTree();
    }
    if(e.key.toLowerCase()==='r' && gameOverFlag) location.reload();
    if(e.key.toLowerCase()==='r' && !gameOverFlag) confirmRestart();
    if(e.code==='Space'&&!paused&&!gameOverFlag){ e.preventDefault(); doDash(); }
    if((e.code==='ShiftLeft'||e.code==='ShiftRight')&&!paused&&!gameOverFlag) doShield();
    if(e.key.toLowerCase()==='e'&&!paused&&!gameOverFlag) doNova();

    if(document.getElementById('levelUI').style.display==='block'){
        if(e.key==='ArrowUp'||e.key.toLowerCase()==='z') { sel=(sel+choices.length-1)%choices.length; renderLevelUI(); }
        if(e.key==='ArrowDown'||e.key.toLowerCase()==='s') { sel=(sel+1)%choices.length; renderLevelUI(); }
        if(['1','2','3','4','5','6','7','8'].includes(e.key)){ e.preventDefault(); applyChoice(+e.key-1); }
        if(e.key==='Enter'){ e.preventDefault(); applyChoice(sel); }
    }
});
addEventListener('keyup', e=>{ keys[e.key.toLowerCase()]=false; });

// ═══════════════════════════════════════════════
// TOUCH — joystick
// ═══════════════════════════════════════════════
const joy = { active:false, id:null, dx:0, dy:0, radius:60 };

function setupJoystick() {
    const zone=document.getElementById('joystickWrap');
    const knob=document.getElementById('joystickKnob');
    if(!zone||!knob) return;

    // Rayon = 45% de la zone pour laisser de la marge
    const getRadius = () => zone.getBoundingClientRect().width * 0.45;

    const setKnob=(dx,dy)=>{
        const r=getRadius();
        // Utilise transform pour éviter reflow
        knob.style.transform=`translate(calc(-50% + ${dx*r}px), calc(-50% + ${dy*r}px))`;
    };

    zone.addEventListener('touchstart',e=>{
        e.preventDefault();
        const t=e.changedTouches[0];
        joy.active=true; joy.id=t.identifier;
        // Recalcule le centre à chaque appui (gère scroll/rotate)
        const r=zone.getBoundingClientRect();
        joy.cx=r.left+r.width/2;
        joy.cy=r.top+r.height/2;
        joy.radius=r.width*0.45;
        // Position immédiate du knob
        const rdx=t.clientX-joy.cx, rdy=t.clientY-joy.cy;
        const dist=Math.hypot(rdx,rdy)||1;
        const clamped=Math.min(dist,joy.radius);
        joy.dx=(rdx/dist)*(clamped/joy.radius);
        joy.dy=(rdy/dist)*(clamped/joy.radius);
        setKnob(joy.dx,joy.dy);
    },{passive:false});

    zone.addEventListener('touchmove',e=>{
        e.preventDefault();
        for(const t of e.changedTouches){
            if(t.identifier!==joy.id) continue;
            const rdx=t.clientX-joy.cx, rdy=t.clientY-joy.cy;
            const dist=Math.hypot(rdx,rdy)||1;
            const clamped=Math.min(dist,joy.radius);
            joy.dx=(rdx/dist)*(clamped/joy.radius);
            joy.dy=(rdy/dist)*(clamped/joy.radius);
            setKnob(joy.dx,joy.dy);
        }
    },{passive:false});

    const end=e=>{
        for(const t of e.changedTouches){
            if(t.identifier===joy.id){
                joy.active=false; joy.id=null; joy.dx=0; joy.dy=0;
                setKnob(0,0);
            }
        }
    };
    zone.addEventListener('touchend',end,{passive:false});
    zone.addEventListener('touchcancel',end,{passive:false});
}

function touchAbility(e, type) {
    e.preventDefault(); e.stopPropagation();
    if(paused||gameOverFlag) return;
    if(type==='dash')   { doDash();   document.getElementById('btnDash').style.transform='scale(0.88)'; setTimeout(()=>document.getElementById('btnDash').style.transform='',120); }
    if(type==='shield') { doShield(); document.getElementById('btnShield').style.transform='scale(0.88)'; setTimeout(()=>document.getElementById('btnShield').style.transform='',120); }
    if(type==='nova')   { doNova();   document.getElementById('btnNova').style.transform='scale(0.88)'; setTimeout(()=>document.getElementById('btnNova').style.transform='',120); }
}

