// ═══════════════════════════════════════════════
// ABILITIES
// ═══════════════════════════════════════════════
function doDash(){
    if(!player.dashReady||player.dashActive) return;
    let dx=0,dy=0;
    if(joy.active){ dx=joy.dx; dy=joy.dy; }
    else {
        if(keys['z']||keys['arrowup'])    dy-=1;
        if(keys['s']||keys['arrowdown'])  dy+=1;
        if(keys['q']||keys['arrowleft'])  dx-=1;
        if(keys['d']||keys['arrowright']) dx+=1;
    }
    if(!dx&&!dy){ dx=Math.cos(player.angle); dy=Math.sin(player.angle); }
    const len=Math.hypot(dx,dy)||1;
    player.dashVX=(dx/len)*24; player.dashVY=(dy/len)*24;
    player.dashFrames=12; player.dashActive=true;
    player.dashReady=false; player.dashCD=player.dashCDMax;
    player.invincible=14;
    snd('dash'); createParticles(player.wx,player.wy,18,'#ff6600');
}
function doShield(){
    if(player.shieldCD>0) return;
    player.shieldActive=true; player.shieldHP=70+player.level*6;
    player.shieldCD=player.shieldCDMax;
    snd('shield'); createParticles(player.wx,player.wy,14,'#8888ff');
}
function doNova(){
    if(!player.novaReady) return;
    player.novaReady=false; player.novaCD=player.novaCDMax;
    snd('nova');
    const R=260, dmg=player.damage*5;
    enemies.forEach(e=>{
        const d=Math.hypot(e.wx-player.wx,e.wy-player.wy);
        if(d<R){
            e.hp-=dmg;
            const a=Math.atan2(e.wy-player.wy,e.wx-player.wx);
            e.pushX=Math.cos(a)*16; e.pushY=Math.sin(a)*16;
            createParticles(e.wx,e.wy,12,e.color);
        }
    });
    for(let a=0;a<48;a++){
        const ang=(a/48)*Math.PI*2;
        particles.push({wx:player.wx,wy:player.wy,vx:Math.cos(ang)*14,vy:Math.sin(ang)*14,life:28,maxLife:28,color:'#ff6600',size:5,type:'nova'});
    }
    flash('rgba(255,100,0,0.2)');
}
function flash(c){
    const f=document.getElementById('screenFlash');
    f.style.background=c; f.style.opacity='0.7';
    setTimeout(()=>{f.style.transition='opacity 0.4s';f.style.opacity='0';},30);
    setTimeout(()=>{f.style.transition='';},500);
}

// ═══════════════════════════════════════════════
// PARTICLES
// ═══════════════════════════════════════════════
function createParticles(wx,wy,count,color,size=3){
    for(let i=0;i<count;i++){
        const sp=2+Math.random()*8, ang=Math.random()*Math.PI*2;
        particles.push({wx,wy,vx:Math.cos(ang)*sp,vy:Math.sin(ang)*sp,
            life:20+Math.random()*25,maxLife:45,color,size:size*(0.5+Math.random()*0.8),type:'default'});
    }
}
function addFloatingText(wx,wy,text,color='#fff',size=15){
    const s=w2s(wx,wy);
    const el=document.createElement('div');
    el.className='dmg-num';
    el.style.cssText=`left:${s.x}px;top:${s.y}px;color:${color};font-size:${size}px`;
    el.textContent=text;
    document.body.appendChild(el);
    let vy=-2,fr=0;
    const step=()=>{
        fr++; el.style.top=(parseFloat(el.style.top)+vy)+'px';
        el.style.opacity=Math.max(0,1-fr/42); vy*=0.92;
        if(fr<42) requestAnimationFrame(step); else el.remove();
    };
    requestAnimationFrame(step);
}

// ═══════════════════════════════════════════════
// DRAW PLAYER — mage pixel art canvas pur
// ═══════════════════════════════════════════════
function drawPlayer(dt){
    const now=Date.now();
    const mag2 = Math.hypot(joy.dx, joy.dy);
    const moving = (joy.active && mag2 > 0.08) ||
        !!(keys['z']||keys['s']||keys['q']||keys['d']||keys['w']||keys['a']||
           keys['arrowup']||keys['arrowdown']||keys['arrowleft']||keys['arrowright']||
           player.dashActive);

    if(moving) player.walkPhase=(player.walkPhase||0)+dt*0.008;
    else if(player.walkPhase) player.walkPhase*=0.8;

    const sc=w2s(player.wx,player.wy);
    const px=sc.x, py=sc.y;
    const facing=Math.cos(player.angle)>=0?1:-1;

    // Trail
    player.trail.push({wx:player.wx,wy:player.wy});
    if(player.trail.length>(player.dashActive?14:4)) player.trail.shift();
    if(player.dashActive){
        player.trail.forEach((t,i)=>{
            const ts=w2s(t.wx,t.wy);
            ctx.save(); ctx.globalAlpha=(i/player.trail.length)*0.38;
            ctx.fillStyle='#ff6600'; ctx.shadowBlur=16; ctx.shadowColor='#ff4400';
            ctx.beginPath(); ctx.arc(ts.x,ts.y,8,0,Math.PI*2); ctx.fill();
            ctx.restore();
        });
    }

    // Blink
    if(player.invincible>0&&Math.floor(now/55)%2===0){ drawPlayerEffects(px,py); return; }

    const bob=moving?Math.sin(player.walkPhase)*3:0;
    const legSw=moving?Math.sin(player.walkPhase)*10:0;
    const armSw=moving?Math.sin(player.walkPhase+Math.PI)*6:0;
    const cloakSway=moving?Math.sin(player.walkPhase*0.5)*4:0;
    const flicker=0.82+Math.sin(now/70)*0.12+Math.sin(now/130)*0.06;

    ctx.save();
    ctx.translate(px, py+bob);
    if(facing<0) ctx.scale(-1,1);

    // Halo sol
    const hg=ctx.createRadialGradient(16,12,0,16,8,52*flicker);
    hg.addColorStop(0,`rgba(255,170,0,${0.2*flicker})`); hg.addColorStop(1,'transparent');
    ctx.fillStyle=hg; ctx.fillRect(-20,-40,100,80);

    // Ombre
    ctx.fillStyle='rgba(0,0,0,0.25)';
    ctx.beginPath(); ctx.ellipse(0,20,12,4,0,0,Math.PI*2); ctx.fill();

    // Jambes
    ctx.fillStyle='#3d2a1a';
    ctx.save(); ctx.translate(-3,8); ctx.rotate((-legSw*0.6)*Math.PI/180);
    ctx.fillRect(-4,0,7,14); ctx.fillStyle='#2a1a0e'; ctx.fillRect(-3,13,6,8); ctx.restore();
    ctx.fillStyle='#4a3320';
    ctx.save(); ctx.translate(3,8); ctx.rotate((legSw*0.6)*Math.PI/180);
    ctx.fillRect(-4,0,7,14); ctx.fillStyle='#331f0e'; ctx.fillRect(-3,13,6,8); ctx.restore();

    // Cape
    ctx.fillStyle=player.dashActive?'#1a1a40':'#111118';
    ctx.shadowBlur=6; ctx.shadowColor='rgba(80,40,100,0.3)';
    ctx.beginPath();
    ctx.moveTo(-14+cloakSway,-10); ctx.lineTo(14+cloakSway*0.5,-10);
    ctx.lineTo(16+cloakSway*0.8,14); ctx.lineTo(-12+cloakSway,14);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle='#2a2230'; ctx.lineWidth=1; ctx.stroke();
    ctx.shadowBlur=0;

    // Ceinture
    ctx.fillStyle='#6b4c1e'; ctx.fillRect(-10,4,20,3);
    ctx.fillStyle='#c8922a'; ctx.fillRect(-3,3,6,5);
    ctx.fillStyle='#7a5010'; ctx.fillRect(-1,4,2,3);

    // Bras gauche
    ctx.fillStyle='#3d2810';
    ctx.save(); ctx.translate(-11,-4); ctx.rotate((armSw*0.6)*Math.PI/180);
    ctx.fillRect(-3,0,6,11);
    ctx.fillStyle='#c8824a'; ctx.beginPath(); ctx.arc(0,12,3.5,0,Math.PI*2); ctx.fill();
    ctx.restore();

    // Bras droit + lanterne
    ctx.fillStyle='#3d2810';
    ctx.save(); ctx.translate(11,-4); ctx.rotate((-armSw*0.4)*Math.PI/180);
    ctx.fillRect(-3,0,6,11);
    ctx.fillStyle='#c8824a'; ctx.beginPath(); ctx.arc(0,11,3.5,0,Math.PI*2); ctx.fill();
    // Lanterne
    const ly=12;
    ctx.strokeStyle='#666'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.moveTo(0,ly-4); ctx.lineTo(0,ly+4); ctx.stroke();
    const lg=ctx.createRadialGradient(0,ly+8,0,0,ly+8,20*flicker);
    lg.addColorStop(0,`rgba(255,200,0,${0.55*flicker})`); lg.addColorStop(0.5,`rgba(255,120,0,${0.25*flicker})`); lg.addColorStop(1,'transparent');
    ctx.fillStyle=lg; ctx.fillRect(-24,ly-2,48,36);
    ctx.fillStyle='#333'; ctx.fillRect(-6,ly+2,12,14); ctx.fillRect(-6,ly,12,4); ctx.fillStyle='#444'; ctx.fillRect(-6,ly+16,12,3);
    const fR=150+Math.sin(now/40)*40|0, fG=90+Math.sin(now/60)*30|0;
    ctx.fillStyle=`rgb(${fR},${fG},0)`; ctx.shadowBlur=10*flicker; ctx.shadowColor='#ff9900';
    ctx.fillRect(-4,ly+4,8,10); ctx.shadowBlur=0;
    ctx.strokeStyle='#666'; ctx.lineWidth=1; ctx.strokeRect(-6,ly,12,20);
    ctx.restore();

    // Torse
    ctx.fillStyle='#181420'; ctx.fillRect(-8,-10,16,16);
    ctx.strokeStyle='rgba(80,60,100,0.35)'; ctx.lineWidth=0.8;
    ctx.beginPath(); ctx.moveTo(-4,-8); ctx.lineTo(-4,4); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(4,-8); ctx.lineTo(4,4); ctx.stroke();

    // Cou
    ctx.fillStyle='#a06030'; ctx.fillRect(-3,-16,6,7);

    // Capuche
    ctx.fillStyle='#08060e';
    ctx.beginPath(); ctx.ellipse(1,-18,9,8,0.1,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#151020'; ctx.shadowBlur=4; ctx.shadowColor='rgba(100,60,150,0.3)';
    ctx.beginPath();
    ctx.moveTo(-12,-12); ctx.quadraticCurveTo(-13,-26,-1,-30);
    ctx.quadraticCurveTo(11,-26,10,-12); ctx.quadraticCurveTo(5,-10,-1,-9);
    ctx.quadraticCurveTo(-7,-10,-12,-12); ctx.closePath(); ctx.fill();
    ctx.shadowBlur=0;
    ctx.strokeStyle='#2a2035'; ctx.lineWidth=1.2; ctx.stroke();
    ctx.fillStyle='#050408';
    ctx.beginPath();
    ctx.moveTo(-8,-13); ctx.quadraticCurveTo(-8,-24,0,-27);
    ctx.quadraticCurveTo(8,-24,7,-13); ctx.quadraticCurveTo(3,-11,0,-11);
    ctx.quadraticCurveTo(-4,-11,-8,-13); ctx.closePath(); ctx.fill();
    // Yeux
    const eyeG=0.4+Math.sin(now/400)*0.15;
    ctx.fillStyle=`rgba(255,180,60,${eyeG})`;
    ctx.beginPath(); ctx.arc(-3,-20,1.8,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(3,-20,1.8,0,Math.PI*2); ctx.fill();

    ctx.restore();
    drawPlayerEffects(px,py);
}

function drawPlayerEffects(px,py){
    if(player.shieldActive){
        ctx.save(); ctx.strokeStyle='#8888ff'; ctx.shadowBlur=18; ctx.shadowColor='#8888ff';
        ctx.globalAlpha=0.5+Math.sin(Date.now()/80)*0.18; ctx.lineWidth=3;
        ctx.beginPath(); ctx.arc(px,py,34,0,Math.PI*2); ctx.stroke(); ctx.restore();
    }
    if(player.aura){
        ctx.save(); ctx.strokeStyle='#ff6600'; ctx.shadowBlur=22; ctx.shadowColor='#ff4400';
        ctx.globalAlpha=0.15+Math.sin(Date.now()/140)*0.07; ctx.lineWidth=5;
        ctx.beginPath(); ctx.arc(px,py,player.auraRadius,0,Math.PI*2); ctx.stroke(); ctx.restore();
    }
}

// ═══════════════════════════════════════════════
// DRAW ENEMY
// ═══════════════════════════════════════════════
const spriteAnims = new WeakMap();
function getSA(e){ if(!spriteAnims.has(e)) spriteAnims.set(e,{frame:Math.floor(Math.random()*4),timer:0}); return spriteAnims.get(e); }

function getSpriteCol(e){
    if(e.boss)              return MOB_COL.zombie;
    if(e.isMini)            return MOB_COL.goblin;
    if(e.type==='fast')     return MOB_COL.skeleton;
    if(e.type==='tank')     return MOB_COL.slime;
    if(e.type==='specter')  return MOB_COL.bat;
    if(e.type==='sniper')   return MOB_COL.skeleton;
    if(e.type==='splitter') return MOB_COL.goblin;
    if(e.isOrblet)          return -1;
    return MOB_COL.rat;
}

function drawEnemy(e, dt){
    const sc=w2s(e.wx,e.wy);
    const ex=sc.x, ey=sc.y;

    // Off-screen cull
    if(ex<-120||ex>canvas.width+120||ey<-120||ey>canvas.height+120) return;

    if(e.isOrblet){
        ctx.save(); ctx.fillStyle=e.color; ctx.shadowBlur=10; ctx.shadowColor=e.color;
        ctx.beginPath(); ctx.arc(ex,ey,5,0,Math.PI*2); ctx.fill(); ctx.restore(); return;
    }

    const sa=getSA(e);
    sa.timer+=dt;
    const fps=MOB_FPS[e.type]||9;
    if(sa.timer>1000/fps){ sa.frame=(sa.frame+1)%4; sa.timer=0; }

    const sprScale=e.boss?0.52:e.isMini?0.38:e.type==='tank'?0.35:e.type==='specter'?0.28:0.30;
    const col=getSpriteCol(e);
    const flipH=(player.wx-e.wx)<0;

    // Shadow
    ctx.save(); ctx.fillStyle='rgba(0,0,0,0.28)';
    const sw2=ssLoaded?Math.round(ssW*sprScale*0.38):18;
    ctx.beginPath(); ctx.ellipse(ex,ey+3,sw2,Math.max(3,sw2*0.28),0,0,Math.PI*2); ctx.fill(); ctx.restore();

    // Boss glow
    if(e.boss){
        ctx.save(); ctx.shadowBlur=38+Math.sin(Date.now()/150)*10; ctx.shadowColor=e.color;
        ctx.globalAlpha=0.45+Math.sin(Date.now()/150)*0.1; ctx.fillStyle=e.color;
        ctx.beginPath(); ctx.arc(ex,ey,26+Math.sin(Date.now()/100)*4,0,Math.PI*2); ctx.fill(); ctx.restore();
    }

    // Sprite
    const drawn=drawMobSprite(col,sa.frame,ex,ey,sprScale,flipH,e.type==='specter');
    if(!drawn) drawFallbackEnemy(e,ex,ey);

    // HP bar
    const bW=e.boss?56:e.isMini?42:30;
    const bY=ey-(ssLoaded?Math.round(ssH*sprScale)*0.9:44)-6;
    ctx.fillStyle='rgba(0,0,0,0.65)'; ctx.fillRect(ex-bW/2,bY,bW,5);
    const hp=Math.max(0,e.hp/e.maxHp);
    ctx.fillStyle=hp>0.5?'#44ee44':hp>0.25?'#ffcc00':'#ff2200';
    ctx.fillRect(ex-bW/2,bY,bW*hp,5);
    ctx.strokeStyle='rgba(0,0,0,0.4)'; ctx.lineWidth=1; ctx.strokeRect(ex-bW/2,bY,bW,5);
}

function drawMobSprite(col,frame,ex,ey,sc,flipH,isSpecter){
    if(col<0||!ssLoaded) return false;
    const src=frameCache[col+'_'+frame];
    if(!src) return false;
    const dw=Math.round(ssW*sc), dh=Math.round(ssH*sc);
    ctx.save();
    if(isSpecter) ctx.globalAlpha=0.35+Math.sin(Date.now()/200)*0.2;
    ctx.imageSmoothingEnabled=true;
    if(flipH){
        ctx.translate(ex,ey-dh*0.42); ctx.scale(-1,1);
        ctx.drawImage(src,0,0,ssW,ssH,-dw/2,0,dw,dh);
    } else {
        ctx.drawImage(src,0,0,ssW,ssH,ex-dw/2,ey-dh*0.85,dw,dh);
    }
    ctx.restore();
    return true;
}

function drawFallbackEnemy(e,ex,ey){
    ctx.save(); ctx.translate(ex,ey);
    ctx.fillStyle=e.color; ctx.shadowBlur=12; ctx.shadowColor=e.color;
    if(e.boss){ ctx.beginPath();for(let i=0;i<10;i++){const a=(i/10)*Math.PI*2-Math.PI/2,r=i%2===0?22:11;if(i===0)ctx.moveTo(Math.cos(a)*r,Math.sin(a)*r);else ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);}ctx.closePath();ctx.fill(); }
    else if(e.isMini){ ctx.beginPath();for(let i=0;i<6;i++){const a=(i/6)*Math.PI*2;if(i===0)ctx.moveTo(Math.cos(a)*18,Math.sin(a)*18);else ctx.lineTo(Math.cos(a)*18,Math.sin(a)*18);}ctx.closePath();ctx.fill(); }
    else if(e.type==='fast'||e.type==='sniper'){ ctx.beginPath();ctx.moveTo(14,0);ctx.lineTo(-9,-7);ctx.lineTo(-5,0);ctx.lineTo(-9,7);ctx.closePath();ctx.fill(); }
    else if(e.type==='tank'){ ctx.beginPath();for(let i=0;i<6;i++){const a=(i/6)*Math.PI*2;if(i===0)ctx.moveTo(Math.cos(a)*14,Math.sin(a)*14);else ctx.lineTo(Math.cos(a)*14,Math.sin(a)*14);}ctx.closePath();ctx.fill(); }
    else if(e.type==='specter'){ const t=Date.now()/300;ctx.beginPath();for(let i=0;i<=32;i++){const a=(i/32)*Math.PI*2,r=9+Math.sin(a*4+t)*3;if(i===0)ctx.moveTo(Math.cos(a)*r,Math.sin(a)*r);else ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);}ctx.closePath();ctx.fill(); }
    else { ctx.beginPath();ctx.arc(0,0,10,0,Math.PI*2);ctx.fill(); }
    ctx.restore();
}
    
// ═══════════════════════════════════════════════
// BACKGROUND DRAW
// ═══════════════════════════════════════════════
function drawTiled(ctx, img, x, y, w, h) {
    if (!img) return;
    const tw = img.width;
    const th = img.height;
    ctx.save();
    ctx.beginPath();
    ctx.rect(x, y, w, h);
    ctx.clip();
    for (let ix = x; ix < x + w; ix += tw) {
        for (let iy = y; iy < y + h; iy += th) {
            ctx.drawImage(img, ix, iy);
        }
    }
    ctx.restore();
}

function drawBackground() {
    const screenX = -cam.x + canvas.width  / 2;
    const screenY = -cam.y + canvas.height / 2;
    const W = WORLD_W;
    const H = WORLD_H;
    const B = W / 4;
    const CW = W - B * 2;
    const CH = H - B * 2;

    ctx.save();
    ctx.translate(screenX, screenY);

    const T = tileImgs;

    if (!T.centre) {
        ctx.fillStyle = '#1a2e0a';
        ctx.fillRect(0, 0, W, H);
        ctx.restore();
        return;
    }

    // CENTRE — mosaïque
    drawTiled(ctx, T.centre, B,     B,     CW, CH);

    // BORDURES — mosaïque
    drawTiled(ctx, T.mh, B,     0,     CW, B);
    drawTiled(ctx, T.mb, B,     H - B, CW, B);
    drawTiled(ctx, T.mg, 0,     B,     B,  CH);
    drawTiled(ctx, T.md, W - B, B,     B,  CH);

    // ANGLES — mosaïque
    drawTiled(ctx, T.hg, 0,     0,     B, B);
    drawTiled(ctx, T.hd, W - B, 0,     B, B);
    drawTiled(ctx, T.bg, 0,     H - B, B, B);
    drawTiled(ctx, T.bd, W - B, H - B, B, B);

    ctx.restore();

    // Couche sombre
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
}


// ═══════════════════════════════════════════════
// DRAW FRAME
// ═══════════════════════════════════════════════
let lastDrawTime=performance.now();
function draw(){
    const now=performance.now();
    const dt=now-lastDrawTime; lastDrawTime=now;

    drawBackground();

    // 🔥 AJOUT VISUEL PORTÉE
    const pr = player.range * player.bulletSpeed;
    const ps = w2s(player.wx, player.wy);
    ctx.beginPath();
    ctx.arc(ps.x, ps.y, pr, 0, Math.PI*2);
    ctx.strokeStyle = "rgba(255,255,255,0.12)";
    ctx.lineWidth = 2;
    ctx.stroke();

function drawChest(x, y, size = 10) {
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(x - size/2, y - size/2, size, size);

    ctx.strokeStyle = '#000';
    ctx.lineWidth = 2;
    ctx.strokeRect(x - size/2, y - size/2, size, size);
}
    // Orbs
    orbs.forEach(o=>{
        if(!o || typeof o.wx === 'undefined') return;
        const s=w2s(o.wx,o.wy);
        if(o.isChest) drawChest(s.x,s.y);
        else {
            ctx.fillStyle='#ffaa00'; ctx.shadowBlur=12; ctx.shadowColor='#ff6600';
            ctx.beginPath(); ctx.arc(s.x,s.y,5,0,Math.PI*2); ctx.fill(); ctx.shadowBlur=0;
        }
    });


    drawPlayer(dt);

    const sorted=[...enemies].sort((a,b)=>a.wy-b.wy);
    sorted.forEach(e=>drawEnemy(e,dt));

    // Bullets
    bullets.forEach(b=>{
        const s=w2s(b.wx,b.wy);
        const sz=3.5+b.wlvl*0.65;
        const c=player.pierce?'#00ccff':b.wlvl>=6?'#ff4400':'#ffcc00';
        ctx.shadowBlur=14; ctx.shadowColor=c; ctx.fillStyle=c;
        ctx.beginPath(); ctx.arc(s.x,s.y,sz,0,Math.PI*2); ctx.fill(); ctx.shadowBlur=0;
    });

    // Homing
    homingBullets.forEach(hb=>{
        const s=w2s(hb.wx,hb.wy);
        ctx.save(); ctx.translate(s.x,s.y); ctx.rotate(Math.atan2(hb.vy,hb.vx));
        ctx.shadowBlur=16; ctx.shadowColor='#f80'; ctx.fillStyle='#f80';
        ctx.beginPath(); ctx.moveTo(8,0); ctx.lineTo(-6,-4); ctx.lineTo(-3,0); ctx.lineTo(-6,4);
        ctx.closePath(); ctx.fill(); ctx.restore();
    });

    // Particles UPDATE + DRAW
for(let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    
    p.life--;
    p.wx += p.vx || 0;
    p.wy += p.vy || 0;
    p.vx = (p.vx || 0) * 0.96;
    p.vy = (p.vy || 0) * 0.96;

    if (p.life <= 0) {
        particles.splice(i, 1);
        continue;
    }

    const s = w2s(p.wx, p.wy);
    ctx.globalAlpha = Math.max(0, p.life / (p.maxLife || 45));
    ctx.fillStyle = p.color;
    ctx.shadowBlur = p.type === 'nova' ? 12 : 0;
    ctx.shadowColor = p.color;
    ctx.fillRect(s.x, s.y, p.size || 3, p.size || 3);
}
ctx.globalAlpha = 1;
ctx.shadowBlur = 0;

drawMinimap();
}

// ═══════════════════════════════════════════════
// MINIMAP
// ═══════════════════════════════════════════════
function drawMinimap(){
    const mw=mCanvas.width, mh=mCanvas.height;
    mctx.clearRect(0,0,mw,mh);
    mctx.fillStyle='rgba(12,4,2,0.85)'; mctx.fillRect(0,0,mw,mh);
    const sx=mw/WORLD_W, sy=mh/WORLD_H;
    enemies.forEach(e=>{
        mctx.fillStyle=e.boss?'#ff00ff':e.color;
        mctx.beginPath(); mctx.arc(e.wx*sx,e.wy*sy,e.boss?4:2,0,Math.PI*2); mctx.fill();
    });
    mctx.fillStyle='#fff'; mctx.shadowBlur=7; mctx.shadowColor='#ff8800';
    mctx.beginPath(); mctx.arc(player.wx*sx,player.wy*sy,4,0,Math.PI*2); mctx.fill();
    mctx.shadowBlur=0;
    mctx.strokeStyle='rgba(255,100,0,0.15)'; mctx.lineWidth=1; mctx.strokeRect(0,0,mw,mh);
}

// ═══════════════════════════════════════════════
// UPDATE
// ═══════════════════════════════════════════════
function update(){
    updateHUD();
    cam.x+=(player.wx-cam.x)*0.12;
    cam.y+=(player.wy-cam.y)*0.12;

    let pdx=0, pdy=0;
    if(joy.active){
        pdx = joy.dx;
        pdy = joy.dy;
    } else {
        if(keys['z']||keys['arrowup'])    pdy-=1;
        if(keys['s']||keys['arrowdown'])  pdy+=1;
        if(keys['q']||keys['arrowleft'])  pdx-=1;
        if(keys['d']||keys['arrowright']) pdx+=1;
        if(keys['w']) pdy-=1;
        if(keys['a']) pdx-=1;
    }

    const dead = joy.active ? 0.08 : 0;
    const mag  = Math.hypot(pdx,pdy);
    if(mag > dead){
        const len = joy.active ? mag : (mag||1);
        const spd = joy.active
            ? player.speed * Math.min(mag/0.3, 1)
            : player.speed;
        player.wx += (pdx/len)*spd;
        player.wy += (pdy/len)*spd;
        player.angle = Math.atan2(pdy, pdx);
    }

    if(player.dashActive){
        player.wx+=player.dashVX; player.wy+=player.dashVY;
        player.dashFrames--; player.dashVX*=0.82; player.dashVY*=0.82;
        if(player.dashFrames<=0) player.dashActive=false;
    }

    player.wx=Math.max(30,Math.min(WORLD_W-30,player.wx));
    player.wy=Math.max(30,Math.min(WORLD_H-30,player.wy));

    const isMobile = navigator.maxTouchPoints > 0;
if(isMobile){
    const tgt = closestEnemy();
    if(tgt) player.angle = Math.atan2(tgt.wy-player.wy, tgt.wx-player.wx);
} else {
        const mwx = mouseX - canvas.width/2 + cam.x;
        const mwy = mouseY - canvas.height/2 + cam.y;
        if(Math.hypot(mouseX-canvas.width/2, mouseY-canvas.height/2) > 10)
            player.angle = Math.atan2(mwy-player.wy, mwx-player.wx);
    }

    if(player.dashCD>0){ player.dashCD--; if(!player.dashCD) player.dashReady=true; }
    if(player.shieldCD>0) player.shieldCD--;
    if(player.novaCD>0){ player.novaCD--; if(!player.novaCD) player.novaReady=true; }
    if(player.invincible>0) player.invincible--;

    if(player.homingMissiles>0){
    player.homingCD--;
    if(player.homingCD<=0){
        player.homingCD=80;
        const tgt=closestEnemy();
        if(tgt) homingBullets.push({wx:player.wx,wy:player.wy,vx:0,vy:-5,target:tgt,damage:player.damage*2.2,life:180});
    }
}

    const now=Date.now();
    if(now-player.lastShot>player.shootDelay){ shoot(); player.lastShot=now; 
    
    }

    // Bullets
    for(let i=bullets.length-1;i>=0;i--){
        const b=bullets[i];
        b.wx+=b.vx; b.wy+=b.vy;
        b.life--;

        let hit=false;
        for(let j=enemies.length-1;j>=0;j--){
            const e=enemies[j];
            if(!e) continue;
            if(e.type==='specter'&&Math.random()>0.55) continue;
            if(Math.hypot(b.wx-e.wx,b.wy-e.wy)<(e.boss?20:e.isMini?18:13)){
                e.hp-=b.damage;
                addFloatingText(e.wx+(Math.random()-0.5)*18,e.wy-18,Math.floor(b.damage),e.boss?'#f0f':'#ff0',e.boss?14:12);
                snd('hit',e.wx);
                if(!player.pierce){bullets.splice(i,1);hit=true;}
                if(e.hp<=0) killEnemy(e,j);
                if(hit) break;
            }
        }
        if(!hit&&(b.life<=0||b.wx<0||b.wx>WORLD_W||b.wy<0||b.wy>WORLD_H)) bullets.splice(i,1);
    }

    // VAGUES
    if(enemies.length===0&&!gameOverFlag&&!paused){
        if(typeof waveTimer==='undefined') waveTimer=0;
        if(waveTimer<=0){
            waveTimer=160;
        } else {
            waveTimer--;
            if(waveTimer<=0) spawnWave();
        }
    }

    // ORBS
for(let i = orbs.length-1; i >= 0; i--){
    const o = orbs[i];
    if(!o || typeof o.wx === 'undefined'){ orbs.splice(i,1); continue; }

    const odx = player.wx - o.wx;
    const ody = player.wy - o.wy;
    const odist = Math.hypot(odx, ody);

    if(odist < 120 && odist > 18){
        const pull = 3.5 / odist;
        o.wx += odx * pull;
        o.wy += ody * pull;
    }

    if(odist < 18){
        // XP
        player.xp += (o.value || 1) * 12;

        // Gold
        gold += o.value || 1;
        goldTotal += o.value || 1;

        if(o.isChest) snd('chest');

        // Level up
        if(player.xp >= player.xpToLevel){
            player.level++;
            player.xp = 0;
            player.xpToLevel = Math.floor(player.xpToLevel * 1.35);
            openLevelUI();
            snd('levelup');
        }

        orbs.splice(i,1);
    }
}

// ENNEMIS → JOUEUR
for(let k = enemies.length-1; k >= 0; k--){
    const e = enemies[k];
    if(!e) continue;

    const edx = player.wx - e.wx;
    const edy = player.wy - e.wy;
    const edist = Math.hypot(edx, edy) || 1;

    e.wx += (edx / edist) * e.speed;
    e.wy += (edy / edist) * e.speed;

    if(player.invincible <= 0 && edist < 28){
        player.hp -= e.damage;
        player.invincible = 45;
        flash('rgba(255,0,0,0.3)');
        snd('hurt', player.wx);
        if(player.hp <= 0) triggerGameOver();
    }
}
}
// ═══════════════════════════════════════════════
// SHOOT
// ═══════════════════════════════════════════════
function shoot(){
    const tgt=closestEnemy(); if(!tgt) return;
    const base=Math.atan2(tgt.wy-player.wy,tgt.wx-player.wx);
    const num=Math.min(1+Math.floor(player.weaponLevel/2),8);
    const spread=0.26-player.weaponLevel*0.016;
    for(let i=0;i<num;i++){
        const a=base+(i-(num-1)/2)*spread;
        bullets.push({
            wx:player.wx,
            wy:player.wy,
            vx:Math.cos(a)*player.bulletSpeed,
            vy:Math.sin(a)*player.bulletSpeed,
            wlvl:player.weaponLevel,
            damage:player.damage,
            life:player.range // 🔥 AJOUT
        });
    }
    if(num>0) snd('shoot',player.wx);
}
function closestEnemy(){
    let best=null,bestD=Infinity;
    enemies.forEach(e=>{
        if(e.type==='specter'&&Math.random()<0.28) return;
        const d=(e.wx-player.wx)**2+(e.wy-player.wy)**2;
        if(d<bestD){bestD=d;best=e;}
    });
    return best;
}


// ═══════════════════════════════════════════════
// SPAWN
// ═══════════════════════════════════════════════
function spawnEnemy(type='normal'){
    const angle = Math.random() * Math.PI * 2;

    const minDist = 500;  // était 300
const dist = minDist + Math.random() * 300;  // était 200

    const tier = Math.floor(waveNumber / 5);

    const baseHP = (8 + player.level * 1.2) * (1 + waveNumber * 0.12) * (1 + tier * 0.4);

    let wx = player.wx + Math.cos(angle) * dist;
    let wy = player.wy + Math.sin(angle) * dist;

    // clamp world
    wx = Math.max(20, Math.min(WORLD_W - 20, wx));
    wy = Math.max(20, Math.min(WORLD_H - 20, wy));

    // sécurité anti spawn trop proche
    const dx = wx - player.wx;
    const dy = wy - player.wy;
    if (Math.hypot(dx, dy) < 200) {
        wx += dx * 2;
        wy += dy * 2;
    }

    const e = {
        wx, wy,
        hp: baseHP,
        maxHp: baseHP,
        speed: 1.5 + waveNumber * 0.05 + Math.floor(waveNumber / 8) * 0.1,
        damage: 1.8 + waveNumber * 0.09,
        boss: false,
        isBlue: false,
        isMini: false, // 🔥 FIX
        color: '#f44',
        type,
        angle: 0,
        pushX: 0,
        pushY: 0
    };

    const m = {
        fast:    {speed:3.8+waveNumber*0.04,hpMult:0.6,color:'#ff0'},
        tank:    {speed:1.0+waveNumber*0.02,hpMult:4.2,damageMult:2.2,color:'#f60'},
        boss:    {speed:1.5+waveNumber*0.03,hpMult:25,damageMult:4.5,boss:true,color:'#c0f'},
        blue:    {speed:2.2+waveNumber*0.03,hpMult:2.2,damageMult:1.5,isBlue:true,color:'#22f'},
        specter: {speed:2.2+waveNumber*0.03,hpMult:1.3,damageMult:1.3,color:'#aaf'},
        miniboss:{speed:1.7+waveNumber*0.02,hpMult:4,damageMult:3.0,isMini:true,color:'#f60'}, // 🔥 NERF
        sniper:  {speed:1.2+waveNumber*0.02,hpMult:1.6,damageMult:2,color:'#f80'},
        splitter:{speed:1.8+waveNumber*0.03,hpMult:1.8,damageMult:1.2,color:'#0f8'},
    };

    if (m[type]){
        const v = m[type];
        if (v.speed)       e.speed = v.speed;
        if (v.hpMult)      { e.hp *= v.hpMult; e.maxHp = e.hp; }
        if (v.damageMult)  e.damage *= v.damageMult;
        if (v.boss)        e.boss = true;
        if (v.isBlue)      e.isBlue = true;
        if (v.isMini)      e.isMini = true;
        if (v.color)       e.color = v.color;
    }

    enemies.push(e);
}

function spawnWave(){
    waveNumber++;
    const tier = Math.floor(waveNumber/5);

    const count = Math.floor(
        (waveNumber<=6 ? 5+waveNumber : 8+waveNumber*1.4) * (1 + tier*0.18)
    );

    const spawnList = [];

    for(let i=0;i<count;i++){
        const r = Math.random();
        if(waveNumber%10===0 && i===0 && !bossAlive)        spawnList.push('boss');
        else if(waveNumber%5===0 && !bossAlive && i===0)    spawnList.push('miniboss');
        else if(waveNumber>10 && r<0.08)  spawnList.push('sniper');
        else if(waveNumber>8  && r<0.14)  spawnList.push('splitter');
        else if(waveNumber>5  && r<0.22)  spawnList.push('specter');
        else if(r<0.32)  spawnList.push('fast');
        else if(r<0.60)  spawnList.push('tank');
        else             spawnList.push('normal');
    }

    // Spawn échelonné : 1 ennemi toutes les 180ms
    spawnList.forEach((type, i) => {
        setTimeout(() => {
            if(type === 'boss' || type === 'miniboss'){
                if(!bossAlive){ spawnEnemy(type); bossAlive = true; }
            } else {
                spawnEnemy(type);
            }
        }, i * 180);
    });

    const txt =
        waveNumber%10===0 ? `⚠️ BOSS — VAGUE ${waveNumber}` :
        waveNumber%5===0  ? `⚡ VAGUE ${waveNumber} — PALLIER` :
                            `VAGUE ${waveNumber}`;

    const wb = document.getElementById('waveBanner');
    wb.textContent = txt;
    wb.style.opacity = '1';
    setTimeout(()=>{wb.style.transition='opacity 0.8s';wb.style.opacity='0';},1400);
    setTimeout(()=>{wb.style.transition='';},2300);
}

// ═══════════════════════════════════════════════
// KILL
// ═══════════════════════════════════════════════
function killEnemy(e, idx) {

    // 🔥 FIX CRITIQUE : suppression de l'ennemi
    if (idx >= 0 && idx < enemies.length) {
        enemies.splice(idx, 1);
    }

    // 🔥 SPLITTER (inchangé logique, juste sécurisé)
    if (e.type === 'splitter' && !e.isSplit) {
        for (let k = 0; k < 2; k++) {
            const a = Math.random() * Math.PI * 2;
            enemies.push({
                wx: e.wx + Math.cos(a) * 20,
                wy: e.wy + Math.sin(a) * 20,
                hp: e.maxHp * 0.35,
                maxHp: e.maxHp * 0.35,
                speed: e.speed * 1.4,
                damage: e.damage * 0.7,
                boss: false,
                isBlue: false,
                isMini: false,
                color: e.color,
                type: 'normal',
                angle: 0,
                pushX: 0,
                pushY: 0,
                isSplit: true
            });
        }
    }

    // ✅ Snapshot unique — UN SEUL push d'orb
    const dropX = e.wx;
    const dropY = e.wy;

    orbs.push({
        wx: dropX,
        wy: dropY,
        value: e.boss ? 6 : e.isMini ? 3 : e.isBlue ? 2 : 1,
        isChest: e.boss || e.isMini || e.isBlue
    });

    createParticles(
        dropX,
        dropY,
        e.boss ? 60 : e.isMini ? 40 : 18,
        e.color,
        e.boss ? 6 : 3
    );

    const pts =
        e.boss ? 600 :
        e.isBlue ? 90 :
        e.type === 'specter' ? 55 :
        e.type === 'sniper' ? 70 :
        15;

    const gm = goldMultiplier();

    const goldGain = Math.floor(
        (e.boss ? 8 + waveNumber :
         e.isBlue ? 3 :
         e.type === 'specter' ? 2 :
         1) * gm * 0.25
    );

    gold += goldGain;
    goldTotal += goldGain;

    score += pts * (1 + Math.floor(combo / 5));

    kills++;
    combo++;
    comboTimer = 85;

    if (combo > maxCombo) maxCombo = combo;

    if (combo >= 3) {
        const c = document.getElementById('hudCombo');
        c.style.opacity = '1';
        c.textContent = `×${combo}`;
    }

    if (e.boss) {
        addKillFeed('💀 BOSS!');
        bossAlive = false;
        snd('death', e.wx);
        flash('rgba(200,0,255,0.3)');
    }
    else if (e.isMini) {
        addKillFeed('⚡ MINI-BOSS');
        bossAlive = false; // 🔥 FIX logique (cohérent avec spawnWave)
        snd('death', e.wx);
    }
    else if (combo >= 5) {
        addKillFeed(`🔥 ×${combo} COMBO`);
        snd('death', e.wx);
    }
    else {
        snd('death', e.wx);
    }
}

function addKillFeed(t) {
    const el = document.createElement('div');
    el.className = 'kill-entry';
    el.textContent = t;

    const kf = document.getElementById('killFeed');
    kf.insertBefore(el, kf.firstChild);

    while (kf.children.length > 5) {
        kf.removeChild(kf.lastChild);
    }

    setTimeout(() => {
        if (el.parentNode) el.remove();
    }, 2500);
}

