function updateHUD(){
    document.getElementById('hudWave').textContent=waveNumber;
    // High score display
    const hsEl=document.getElementById('hudHS');
    if(hsEl) hsEl.textContent='🏆 '+highScore.toLocaleString();
    document.getElementById('hudLevel').textContent=player.level;
    document.getElementById('hudScore').textContent=score.toLocaleString();
    document.getElementById('hudGold').textContent='🪙'+gold;
    const hp=Math.max(0,player.hp/player.maxHp*100);
    document.getElementById('barHp').style.width=hp+'%';
    document.getElementById('hudHpVal').textContent=Math.floor(player.hp)+'/'+player.maxHp;
    const xp=player.xp/player.xpToLevel*100;
    document.getElementById('barXp').style.width=xp+'%';
    document.getElementById('hudXpVal').textContent=player.xp+'/'+player.xpToLevel;

    // Ability cooldowns
    updCD('btnDash','cdDash',player.dashCD,player.dashCDMax,player.dashReady);
    updCD('btnShield','cdShield',player.shieldCD,player.shieldCDMax,!player.shieldCD);
    updCD('btnNova','cdNova',player.novaCD,player.novaCDMax,player.novaReady);

    // Sidebar
    const sb=n=>document.getElementById(n);
    if(sb('sbDmg')) sb('sbDmg').textContent=player.damage.toFixed(1);
    if(sb('sbSpeed')) sb('sbSpeed').textContent=player.speed.toFixed(1);
    if(sb('sbWeapon')) sb('sbWeapon').textContent=player.weaponLevel;
    if(sb('sbKills')) sb('sbKills').textContent=kills;
    if(sb('sbCombo')) sb('sbCombo').textContent='×'+maxCombo;
    if(sb('sbRegen')) sb('sbRegen').textContent=player.regen.toFixed(2);
    if(sb('sbPierce')) sb('sbPierce').textContent=player.pierce?'✅':'❌';
    if(sb('sbAura')) sb('sbAura').textContent=player.aura?`✅r${Math.floor(player.auraRadius)}`:'❌';
}

function updCD(btnId,cdId,cd,maxCD,ready){
    const btn=document.getElementById(btnId);
    const cdEl=document.getElementById(cdId);
    if(!btn||!cdEl) return;
    if(cd>0){ btn.classList.add('on-cd'); cdEl.textContent=Math.ceil(cd/60)+'s'; }
    else { btn.classList.remove('on-cd'); }
}

// ═══════════════════════════════════════════════
// LEVEL UP UI
// ═══════════════════════════════════════════════
const upgradeDescs={
    '⚔️ +4 Dégâts':'Dégâts de base des projectiles',
    '🏃 +1 Vitesse':'Vitesse de déplacement',
    '❤️ +Regen':'Régénération HP passive',
    '🌌 Activer Aura':'Zone de dégâts autour de vous',
    '🌌 Aura +':'Agrandit rayon et dégâts aura',
    '🔫 +Arme':'3 stacks = niveau arme supérieur',
    '🛡️ +45 PV':'Augmente PV maximum',
    '⚡ +Bullet Speed':'Vitesse des projectiles',
    '💫 +Nova Power':'Réduit cooldown de la Nova',
};

function openLevelUI(){
    paused=true; levelUIOpenTime=Date.now();
    choices=[
        {name:'⚔️ +4 Dégâts',      apply:()=>player.damage+=4},
        {name:'🏃 +1 Vitesse',     apply:()=>player.speed+=1},
        {name:'❤️ +Regen',         apply:()=>player.regen+=0.4},
        {name:player.aura?'🌌 Aura +':'🌌 Activer Aura', apply:()=>{
            if(!player.aura){player.aura=true;player.auraRadius=70;player.auraDamage=0.22;}
            else{player.auraRadius+=16;player.auraDamage+=0.17;}
        }},
        {name:'🔫 +Arme', apply:()=>{player.weaponXP++;if(player.weaponXP>=3){player.weaponXP=0;player.weaponLevel++;player.shootDelay=Math.max(35,player.shootDelay-10);}}},
        {name:'🛡️ +45 PV',        apply:()=>{player.maxHp+=45;player.hp+=45;}},
        {name:'⚡ +Bullet Speed',  apply:()=>player.bulletSpeed+=1.5},
        {name:'💫 +Nova Power',    apply:()=>{player.novaCDMax=Math.max(200,player.novaCDMax-55);}},
    ];
    sel=0; renderLevelUI();
    document.getElementById('levelUI').style.display='block';
}

function renderLevelUI(){
    let items='';
    choices.forEach((c,i)=>{
        const d=upgradeDescs[c.name]||'';
        items+=`<div class="choice-item${i===sel?' selected':''}" data-idx="${i}"
            style="touch-action:manipulation">
            <div style="font-weight:bold">${i+1}. ${c.name}</div>
            ${d?`<div class="choice-desc">${d}</div>`:''}
        </div>`;
    });
    document.getElementById('levelUI').innerHTML=`
        <h2>↑ NIVEAU ${player.level}</h2>
        <div id="choiceList" style="overflow-y:auto;max-height:55vh;-webkit-overflow-scrolling:touch">${items}</div>
        <div style="margin-top:10px;font-size:9px;color:#444;letter-spacing:2px">TAPER · 1-8 · ENTRÉE</div>`;

    // Touch events
    setTimeout(()=>{
        const list=document.getElementById('choiceList');
        if(!list) return;
        let startY=0, scrolled=false;
        list.addEventListener('touchstart',e=>{startY=e.touches[0].clientY;scrolled=false;},{passive:true});
        list.addEventListener('touchmove', e=>{if(Math.abs(e.touches[0].clientY-startY)>8)scrolled=true;},{passive:true});
        list.querySelectorAll('[data-idx]').forEach(el=>{
            el.addEventListener('touchend',e=>{
                if(scrolled) return;
                e.preventDefault();
                applyChoice(parseInt(el.dataset.idx));
            });
            el.addEventListener('click',()=>applyChoice(parseInt(el.dataset.idx)));
        });
    },50);
}

function applyChoice(i){
    if(i<0||i>=choices.length) return;
    if(Date.now()-levelUIOpenTime<350) return; // anti-accidental tap
    choices[i].apply();
    document.getElementById('levelUI').style.display='none';
    paused=false;
}

function triggerGameOver(){
    gameOverFlag=true;
    if(score>highScore){highScore=score;localStorage.setItem('vsHS17',highScore);}

    // ── SAUVEGARDE DASHBOARD ──
    const prevGold=parseInt(localStorage.getItem('vs_gold')||'0');
    localStorage.setItem('vs_gold', prevGold+goldTotal);

    const prevTotalGold=parseInt(localStorage.getItem('vs_totalGold')||'0');
    localStorage.setItem('vs_totalGold', prevTotalGold+goldTotal);

    const prevKills=parseInt(localStorage.getItem('vs_totalKills')||'0');
    localStorage.setItem('vs_totalKills', prevKills+kills);

    const prevWaves=parseInt(localStorage.getItem('vs_wavesBeaten')||'0');
    localStorage.setItem('vs_wavesBeaten', Math.max(prevWaves, waveNumber-1));

    const prevGames=parseInt(localStorage.getItem('vs_gamesPlayed')||'0');
    localStorage.setItem('vs_gamesPlayed', prevGames+1);

    localStorage.setItem('vs_hs', highScore);

    const prevBestCombo=parseInt(localStorage.getItem('vs_bestCombo')||'0');
    if(maxCombo>prevBestCombo) localStorage.setItem('vs_bestCombo', maxCombo);
    // ── FIN SAUVEGARDE ──

    const t=Math.floor(performance.now()/1000);
    document.getElementById('gameOverUI').innerHTML=`
        <h2 style="color:#f44">GAME OVER</h2><br>
        <div class="stat-row"><span>Score</span><span class="stat-val">${score.toLocaleString()}</span></div>
        <div class="stat-row"><span>Record</span><span class="stat-val">${highScore.toLocaleString()} ${score>=highScore?'🏆':''}</span></div>
        <div class="stat-row"><span>Vague</span><span class="stat-val">${waveNumber}</span></div>
        <div class="stat-row"><span>Niveau</span><span class="stat-val">${player.level}</span></div>
        <div class="stat-row"><span>Kills</span><span class="stat-val">${kills}</span></div>
        <div class="stat-row"><span>Max combo</span><span class="stat-val">×${maxCombo}</span></div>
        <div class="stat-row"><span>Durée</span><span class="stat-val">${Math.floor(t/60)}m ${t%60}s</span></div>
        <div class="stat-row"><span>Or gagné</span><span class="stat-val">🪙 ${goldTotal}</span></div>
        <br>
        <p style="font-size:10px;color:rgba(255,215,0,0.45);margin-bottom:12px;font-family:'Share Tech Mono',monospace">L'or est conservé → améliore ton build !</p>
        <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
            <button onclick="returnToDashboard()" style="border-color:#ffd700;color:#ffd700">⬅ MENU</button>
            <button onclick="location.reload()">↺ REJOUER</button>
        </div>`;
    document.getElementById('gameOverUI').style.display='block';
}

// ═══════════════════════════════════════════════
// UPGRADE TREE
// ═══════════════════════════════════════════════
const UPGRADES=[
    {id:'hp',    icon:'❤️', name:'BLINDAGE',       desc:'PV max +25/niv',              maxLvl:12,baseCost:15,costMult:1.7},
    {id:'dmg',   icon:'⚔️', name:'ARMEMENT',       desc:'Dégâts +2.5/niv',             maxLvl:12,baseCost:18,costMult:1.8},
    {id:'speed', icon:'💨', name:'PROPULSION',     desc:'Vitesse +0.4/niv',             maxLvl:8, baseCost:14,costMult:1.6},
    {id:'regen', icon:'🔋', name:'NANO-REPAIR',    desc:'Regen HP +0.35/niv',           maxLvl:8, baseCost:22,costMult:1.9},
    {id:'shoot', icon:'🔫', name:'CADENCE',        desc:'Tir -10ms délai/niv',          maxLvl:8, baseCost:25,costMult:2.0},
    {id:'bspeed',icon:'⚡', name:'VÉLOCITÉ',       desc:'Vitesse balle +1/niv',         maxLvl:6, baseCost:18,costMult:1.7},
    {id:'dashcd',icon:'🌀', name:'DASH AMÉLIORÉ',  desc:'CD dash -18fr/niv',            maxLvl:5, baseCost:35,costMult:2.4},
    {id:'nova',  icon:'💥', name:'NOVA RENFORCÉE', desc:'CD Nova -70fr/niv',            maxLvl:5, baseCost:45,costMult:2.5},
    {id:'aura',  icon:'🌌', name:'AURA PRIMAIRE',  desc:'Active aura +20r/niv',         maxLvl:6, baseCost:30,costMult:2.1},
    {id:'pierce',icon:'🎯', name:'PERFORATION',    desc:'Balles traversent',            maxLvl:1, baseCost:80,costMult:1.0},
    {id:'homing',icon:'🚀', name:'MISSILES',       desc:'+1 missile guidé',             maxLvl:4, baseCost:55,costMult:2.8},
    {id:'gold',  icon:'🪙', name:'RECYCLAGE',      desc:'+20% or par kill',             maxLvl:5, baseCost:20,costMult:2.0},
];
const UPG_APPLY={
    hp:    ()=>{player.maxHp+=25;player.hp+=25;},
    dmg:   ()=>{player.damage+=2.5;},
    speed: ()=>{player.speed+=0.4;},
    regen: ()=>{player.regen+=0.35;},
    shoot: ()=>{player.shootDelay=Math.max(30,player.shootDelay-10);},
    bspeed:()=>{player.bulletSpeed+=1;},
    dashcd:()=>{player.dashCDMax=Math.max(60,player.dashCDMax-18);},
    nova:  ()=>{player.novaCDMax=Math.max(150,player.novaCDMax-70);},
    aura:  ()=>{if(!player.aura){player.aura=true;player.auraRadius=60;player.auraDamage=0.18;}else{player.auraRadius+=20;player.auraDamage+=0.16;}},
    pierce:()=>{player.pierce=true;},
    homing:()=>{player.homingMissiles++;},
    gold:  ()=>{},
};
function goldMultiplier(){return 1+upgLevels['gold']*0.20;}
const savedUpg=JSON.parse(localStorage.getItem('vsUpg17')||'{}');
const upgLevels={};
UPGRADES.forEach(u=>upgLevels[u.id]=savedUpg[u.id]||0);
function saveUpg(){localStorage.setItem('vsUpg17',JSON.stringify(upgLevels));}
function getUpgCost(u){return Math.floor(u.baseCost*Math.pow(u.costMult,upgLevels[u.id]));}
function applyAllSaved(){UPGRADES.forEach(u=>{for(let i=0;i<upgLevels[u.id];i++) UPG_APPLY[u.id]();});}

function openUpgradeTree(){
    paused=true;
    const el=document.getElementById('upgradeOverlay');
    if(!el) return;
    document.getElementById('upgradeGold').textContent='🪙 '+gold;
    renderUpgradeGrid();
    el.style.display='block';
    el.style.zIndex='400';
}
function closeUpgradeTree(){
    const el=document.getElementById('upgradeOverlay');
    if(el) el.style.display='none';
    if(!gameOverFlag) paused=false;
}
function renderUpgradeGrid(){
    const grid=document.getElementById('upgradeGrid');
    grid.innerHTML='';
    UPGRADES.forEach(u=>{
        const lvl=upgLevels[u.id], isMax=lvl>=u.maxLvl;
        const cost=isMax?0:getUpgCost(u), canAfford=gold>=cost;
        const pct=(lvl/u.maxLvl*100).toFixed(0);
        const card=document.createElement('div');
        card.className='upg-card'+(isMax?' maxed':!canAfford?' cant-afford':'');
        card.innerHTML=`<div class="upg-icon">${u.icon}</div><div class="upg-name">${u.name}</div><div class="upg-desc">${u.desc}</div><div style="font-size:9px;color:rgba(0,255,150,0.6);margin-bottom:4px">Niveau ${lvl}/${u.maxLvl}</div><div class="upg-cost ${isMax?'maxed':''}">${isMax?'✅ MAXÉ':'🪙 '+cost}</div><div class="upg-bar"><div class="upg-bar-fill" style="width:${pct}%"></div></div>`;
        if(!isMax&&canAfford) card.onclick=()=>buyUpg(u);
        grid.appendChild(card);
    });
    document.getElementById('upgradeGold').textContent='🪙 '+gold;
}
function buyUpg(u){
    if(gold<getUpgCost(u)||upgLevels[u.id]>=u.maxLvl) return;
    gold-=getUpgCost(u); upgLevels[u.id]++;
    UPG_APPLY[u.id](); saveUpg(); snd('chest'); renderUpgradeGrid();
}

// ═══════════════════════════════════════════════
// TITLE SCREEN
// ═══════════════════════════════════════════════
const titleCanvas=document.getElementById('titleCanvas');
const tctx=titleCanvas.getContext('2d');
let titleStars=[], titleRunning=true;
function initTitle(){
    titleCanvas.width=innerWidth; titleCanvas.height=innerHeight;
    titleStars=Array.from({length:180},()=>({
        x:Math.random()*innerWidth, y:Math.random()*innerHeight+innerHeight,
        r:Math.random()*2+0.4, speed:-(Math.random()*0.7+0.2),
        hue:18+Math.random()*28
    }));
}
function drawTitle(){
    tctx.fillStyle='rgba(10,2,0,0.15)'; tctx.fillRect(0,0,titleCanvas.width,titleCanvas.height);
    titleStars.forEach(s=>{
        s.y+=s.speed; if(s.y<-10){s.y=titleCanvas.height+10;s.x=Math.random()*titleCanvas.width;}
        tctx.globalAlpha=0.5+Math.sin(Date.now()/400+s.x)*0.35;
        tctx.fillStyle=`hsl(${s.hue},100%,${60+Math.sin(Date.now()/300+s.x)*15}%)`;
        tctx.beginPath(); tctx.arc(s.x,s.y,s.r,0,Math.PI*2); tctx.fill();
    });
    tctx.globalAlpha=1;
    if(titleRunning) requestAnimationFrame(drawTitle);
}
initTitle(); drawTitle();
const hsVal=parseInt(localStorage.getItem('vsHS17')||'0');
document.getElementById('titleHS').textContent=hsVal>0?'🏆 RECORD : '+hsVal.toLocaleString():'';

