// PAUSE / RESTART
// ═══════════════════════════════════════════════
function togglePause(){
    if(gameOverFlag) return;
    paused=!paused;
    const o=document.getElementById('pauseOverlay');
    const b=document.getElementById('pauseBtn');
    if(o) paused?o.classList.add('active'):o.classList.remove('active');
    if(b) b.textContent=paused?'▶':'⏸';
    if(paused && AC.state==='running') AC.suspend();
    else if(!paused && AC.state==='suspended') AC.resume();
}
function confirmRestart(){ if(confirm('Recommencer ? (L\'or est conservé)')) location.reload(); }

// ═══════════════════════════════════════════════
// START
// ═══════════════════════════════════════════════
function startGame(){
    if(AC.state==='suspended') AC.resume();
    titleRunning=false;
    document.getElementById('titleScreen').style.transition='opacity 0.5s';
    document.getElementById('titleScreen').style.opacity='0';
    setTimeout(()=>document.getElementById('titleScreen').style.display='none',500);

    // Loading indicator
    const ld=document.createElement('div');
    ld.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);font-family:Orbitron,monospace;color:#ff8800;font-size:16px;letter-spacing:4px;z-index:500;background:rgba(6,2,1,0.92);padding:20px 30px;border-radius:12px;border:1px solid rgba(255,120,0,0.3)';
    ld.textContent='CHARGEMENT...';
    document.body.appendChild(ld);

    loadAssets(()=>{
        ld.remove();
        resize();
        applyAllSaved();
        setupJoystick();
        // Init HS
        const hsEl=document.getElementById('hudHS');
        if(hsEl) hsEl.textContent='🏆 '+highScore.toLocaleString();
        spawnWave(); updateHUD(); loop();
    });
}

// ═══════════════════════════════════════════════
// LOOP
// ═══════════════════════════════════════════════
function loop(){
    if(!paused&&!gameOverFlag) update();
    draw();
    requestAnimationFrame(loop);
}
